        return strFinal;
    }

    @Benchmark
    public StringBuffer benchmarkStringBufferReplacement() {
        StringBuffer stringBuffer = new StringBuffer(strInitial);
        stringBuffer.replace(0,6, replacement);
        return stringBuffer;
